            // TODO API_TEST_START
            java.io.File outFile = outputPath.resolve("test_write.png").toFile();
            net.coobird.thumbnailator.tasks.io.ImageSink<java.io.File> sink = new net.coobird.thumbnailator.tasks.io.FileImageSink(outFile);
            sink.setOutputFormatName("png");

            try {
                sink.write(sourceImage);
            } catch (net.coobird.thumbnailator.tasks.UnsupportedFormatException e) {
                System.err.println("Format not supported by JVM Image I/O: " + e.getMessage());
                throw new RuntimeException(e);
            } catch (java.io.IOException e) {
                System.err.println("Failed to write thumbnail: " + e.getMessage());
                throw new RuntimeException(e);
            }

            assert outFile.exists() : "Output file should exist";
            assert outFile.length() > 0 : "Output file should not be empty";

            java.awt.image.BufferedImage readBack = javax.imageio.ImageIO.read(outFile);
            assert readBack != null : "Should be able to read back the written image";
            assert readBack.getWidth() == sourceImage.getWidth() : "Width should match";
            assert readBack.getHeight() == sourceImage.getHeight() : "Height should match";

            System.out.println("__CHECK__ write " + readBack.getWidth() + "x" + readBack.getHeight());
            // TODO API_TEST_END
            System.out.println("__DONE__");
        } catch (Throwable exc) {
            System.err.println("__RUN_ERR__ " + exc.getClass().getSimpleName()
                    + ": " + exc.getMessage());
            exc.printStackTrace(System.err);
            System.exit(1);
        }
    }
}
